def mru_cache(maxsize=128, typed=False):
    cache = {}
    use_count = {}

    def wrapper(*args, **kwargs):
        key = (args, frozenset(kwargs.items()))
        if key in cache:
            use_count[key] += 1
        else:
            use_count[key] = 1
            if len(cache) > maxsize:
                least_used = min(use_count, key=use_count.get)
