def minimalBases(classes):
    # Helper method to determine the smallest base class from a set of bases
    def find_min_base(bases):
        return min(bases, key=lambda b: id(b))

    # Initialize the result list with the smallest base class from the first base class in the list
    result = [find_min_base(classes)]

    # Iterate over the remaining base classes
    for base in classes[1:]:
        # Add the smallest base class found in the following order
        smallest_base = find_min_base([base] + result)
        if base != smallest_base:
            result.append(smallest_base)

    # Return the ordered minimum equivalent list of base classes
    return result

