def _normalizeargs(sequence, output=None):
    if not sequence:
        return

    normalized_sequence = []
    for item in sequence:
        if isinstance(item, interface_declaration):
            normalized_sequence.append(item.name)
        elif isinstance(item, interface):
            normalized_sequence.append(item.name)
        elif isinstance(item, tuple):
            normalized_sequence.extend([x.name for x in item])
        elif isinstance(item, declaration):
            normalized_sequence.append(item.name)
        else:
            # if we get something like this in the input
            # itertools is required to fully resolve from
            # the subclasses/containing info
            from itertools import chain
            nested_items = chain(item.this, item.thisexpr)
            normalized_sequence.extend([n.name for n in nested_items])

    if output is not None:
        output.extend(normalized_sequence)
    else:
        return normalized_sequence

