def formatmany(
    self,
    sql: AnyStr,
    many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    # Convert the SQL query
    if isinstance(sql, bytes):
        sql = sql.decode('utf-8')
    formatted_sql = sql.replace("{%", "?").replace("%}", "")  # Assuming "{'%'}" and "%{'%"'}" are placeholders for in-style parameters

    # Convert each set of parameters
    converted_params = []
    for params in many_params:
        if isinstance(params, Mapping):
            converted_params.append(params)  # Use the entire mapping as out-style parameter
        elif isinstance(params, Sequence):
            out_style_params = []
            for param in params:
                out_style_params.append(str(param))  # Convert each sequence element to a string as out-style parameter
            converted_params.append(out_style_params)

    return formatted_sql, converted_params

