    # Collect errors and raise them as a single Invalid exception
    errors = []
    for method in missing_methods:
        errors.append(f'Method {method} is missing in {candidate}')
    for attribute in missing_attributes:
        errors.append(f'Attribute {attribute} is missing in {candidate}')

