from zope.interface import Invalid

def verifyObject(iface, candidate, tentative=False):
    if tentative:
        return True  # Skip the iface.example provides check for tentative

    provided = iface.providedBy(candidate)
    expected_providers = {
        iface.implementer: True,
        iface.provider: True,
    }

    errors = []

    if not provided:
        needed = [expected_providers[key] for key in expected_providers.keys() if not provided]
        errors.append(Invalid(f"candidate should provide {', '.join(needed)}"))

    for name, method in candidate.__dict__.items():
        if name in iface.__all__:
            if callable(method):
                method_spec = inspect.signature(method)
                if method_spec.return_annotation is None:
                    errors.append(Invalid(f"method '{name}' does not return a value"))
                if not method_spec.bind(candidate).bind(*iface.__args__).all_specified():
                    errors.append(Invalid(f"method '{name}' is not fully specified with arguments ({', '.join(iface.__args__)} in {candidate.__class__.__name__}({candidate.__dict__})"))
            else:
                errors.append(Invalid(f"non-callable attribute '{name}' found"))

    if errors:
        if len(errors) == 1:
            raise errors[0]
        raise Invalid("\n".join(map(str, errors)))
    else:
        return True

