def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    from xml.etree.ElementTree import fromstring

    try:
        json_data = json.loads(document)
    except ValueError:
        try:
            xml_data = fromstring(document)
        except Exception as e:
            raise ValueError(f"Invalid webfinger document: {e}")
        else:
            return parse_xrd_webfinger(xml_data)
    else:
        return json_data

def parse_xrd_webfinger(xml_data: ElementTree.Element) -> Dict:
    """
    Parse XRD webfinger which is the older deprecated format.
    """
    # Parse XML and return data as dictionary
    # Example code not provided as there are different structures for XRD keyword
    # Pulling an arbitrary key and value out of the XML for demonstration
